<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import {useDb} from '../../../stores/db'
import {StatusBadge,PreviewBanner} from '../../../components/shared'
const route=useRoute(),db=useDb(),section=computed(()=>String(route.params.section||'users')),importText=ref('staff.one@example.com,viewer\nstaff.two@example.com,admin'),preview=ref<string[]>([])
const permissionRows=[['view','Role-scoped record view'],['act','Create and change records'],['approve','Approve maker-checked work'],['execute','Execute approved money actions'],['publish','Publish approved content'],['export','Generate scoped exports']]
function previewImport(){const emails=new Set<string>();preview.value=importText.value.split('\n').filter(Boolean).map((line,index)=>{const [email,role]=line.split(',');if(!email.includes('@'))return `Row ${index+1}: invalid email`;if(emails.has(email))return `Row ${index+1}: duplicate email`;emails.add(email);if(!role)return `Row ${index+1}: missing role`;return `Row ${index+1}: ready`})}
</script>
<template><div class="page"><header class="page-header"><div><p class="eyebrow">Superadmin controls</p><h1>{{section[0].toUpperCase()+section.slice(1)}}</h1><p>Access is deny-by-default; organisation membership alone grants no record.</p></div><StatusBadge label="Admin only"/></header><template v-if="section==='assignments'"><section class="card table-scroll"><h2>Assignments</h2><el-table :data="db.data.assignments"><el-table-column prop="userId" label="User"/><el-table-column prop="orgId" label="Organisation"/><el-table-column prop="scopeType" label="Scope"/><el-table-column prop="scopeId" label="Scope ID"/><el-table-column prop="role" label="Role"/></el-table></section></template><section v-else-if="section==='roles'" class="card"><h2>Roles and permissions</h2><p>Admin has no default private-file or money authority.</p><el-table :data="permissionRows"><el-table-column prop="0" label="Action"/><el-table-column prop="1" label="Meaning"/></el-table></section><section v-else-if="section==='changes'" class="card"><h2>Change control</h2><PreviewBanner/><div class="data-list"><article class="data-row"><span>Template v3 → v4</span><StatusBadge label="Preview required"/></article><article class="data-row"><span>Emergency support</span><StatusBadge label="Named actor and time limit"/></article></div></section><section v-else-if="section==='imports'" class="card"><h2>Staff email import preview</h2><textarea v-model="importText" rows="5" aria-label="Staff import preview"></textarea><el-button @click="previewImport">Preview</el-button><p v-for="line in preview" :key="line" :class="{'form-error':line.includes('invalid')||line.includes('duplicate')}">{{line}}</p></section><section v-else class="card"><h2>{{section==='partners'?'Partner onboarding':'Staff accounts'}}</h2><p>{{section==='partners'?'Verify → Invite → Assign → Offboard. Expired invitations and removed assignments cannot reuse saved links.':'Individual staff accounts only. Superadmin creates or imports email records; no SSO.'}}</p><div class="card-grid"><article class="card"><h3>Verify</h3><StatusBadge label="Organisation and named individual"/></article><article class="card"><h3>Invite</h3><StatusBadge label="Expiring individual account"/></article><article class="card"><h3>Assign</h3><StatusBadge label="Case scope and dates"/></article></div></section></div></template>
